 public static final class Entry {public final int phase;public final String role;public final List<VisionPoint> body;public final List<List<VisionPoint>> regions,identity,context,anchors;Entry(int p,String r,List<VisionPoint>b,List<List<VisionPoint>>f,List<List<VisionPoint>>i,List<List<VisionPoint>>c,List<List<VisionPoint>>a){phase=p;role=r;body=b;regions=f;identity=i;context=c;anchors=a;}}
 private static void add(String path,int phase,String role,String component,int w,int h,List<VisionPoint>b,List<List<VisionPoint>>f,List<List<VisionPoint>>i,List<List<VisionPoint>>c){
  add(path,phase,role,component,w,h,b,f,i,c,Collections.emptyList());
 }
 private static void add(String path,int phase,String role,String component,int w,int h,List<VisionPoint>b,List<List<VisionPoint>>f,List<List<VisionPoint>>i,List<List<VisionPoint>>c,List<List<VisionPoint>>a){
  ComponentReferenceSpec s=spec("p"+phase+"scene_"+role+"_"+path,component,w,h,path,phase,b,f);REFS.put(path,s);ENTRIES.put(path,new Entry(phase,role,b,f,i,c,a));
  if(!role.equals("protected")&&!role.equals("stacked")&&!role.equals("assembly")&&!role.endsWith("bad")&&!role.equals("back"))INDIVIDUAL.add(spec("video1011_"+path,component,w,h,path,0,b,Collections.singletonList(b)));
 }
 private static ComponentReferenceSpec spec(String id,String component,int w,int h,String path,int phase,List<VisionPoint>b,List<List<VisionPoint>>f){return ComponentReferenceSpec.builder(id,component,"Reviewed "+component,w,h).jpegAssetPath(path).assemblyStepNumber(phase).maximumImageDimension(1280).planarReferenceCornersNormalized(b.get(0),b.get(1),b.get(2),b.get(3)).featureRegionsNormalized(f).polarityAnchorsVerified(false).build();}
 public static ComponentReferenceSpec find(String path){return REFS.get(path);}
 public static Entry annotation(String path){return ENTRIES.get(path);}
 public static Collection<ComponentReferenceSpec> all(){return Collections.unmodifiableCollection(REFS.values());}
 public static List<ComponentReferenceSpec> individual(){return Collections.unmodifiableList(INDIVIDUAL);}
 private static List<VisionPoint> q(double...v){List<VisionPoint> p=new ArrayList<>();for(int n=0;n<v.length;n+=2)p.add(new VisionPoint(v[n],v[n+1]));return Collections.unmodifiableList(p);}
